import { cp, mkdir, readdir, rm } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const output = path.join(root, 'dist');
const source = path.join(root, 'frontend');
// dist is exclusively generated by this script, never a source directory.
const entries = await readdir(source);
await rm(output, { recursive: true, force: true });
await mkdir(output, { recursive: true });
for (const name of entries) {
  if (/\.test\.(mjs|cjs|js)$/.test(name) || name === 'tests') continue;
  await cp(path.join(source, name), path.join(output, name), { recursive: true });
}
const katex = path.join(root, 'node_modules/katex');
await cp(path.join(katex, 'dist'), path.join(output, 'vendor/katex'), { recursive: true });
await cp(path.join(katex, 'LICENSE'), path.join(output, 'vendor/katex/LICENSE'));
await cp(path.join(root, 'licenses'), path.join(output, 'licenses'), { recursive: true });
await cp(path.join(root, 'THIRD_PARTY_NOTICES.md'), path.join(output, 'THIRD_PARTY_NOTICES.md'));
await cp(path.join(root, 'docs/dependency-licenses.json'), path.join(output, 'licenses/dependency-licenses.json'));
console.log('Built offline frontend assets in dist/.');
